class BitStatusUtil:
    ERR_NON_NEGATIVE = "{arg} must be greater than or equal to 0"
    ERR_EVEN = "{arg} must be even"

    @staticmethod
    def add(states, stat):
        BitStatusUtil.check([states, stat])
        return states | stat

    @staticmethod
    def has(states, stat):
        BitStatusUtil.check([states, stat])
        return (states & stat) == stat

    @staticmethod
    def remove(states, stat):
        BitStatusUtil.check([states, stat])
        if BitStatusUtil.has(states, stat):
            return states ^ stat
        return states

    @staticmethod
    def check(args):
        for arg in args:
            if arg < 0:
                raise ValueError(BitStatusUtil.ERR_NON_NEGATIVE.format(arg=arg))
            if arg % 2 != 0:
                raise ValueError(BitStatusUtil.ERR_EVEN.format(arg=arg))

    @staticmethod
    def validate_arg(arg):
        if arg < 0:
            raise ValueError(BitStatusUtil.ERR_NON_NEGATIVE.format(arg=arg))
        if arg % 2 != 0:
            raise ValueError(BitStatusUtil.ERR_EVEN.format(arg=arg))
